{
  "name": "@huynle/opencode-voice",
  "version": "0.6.0",
  "description": "Renamed to @huynle/hub. This release re-exports @huynle/hub so existing installs keep working.",
  "license": "MIT",
  "author": "Huy Le",
  "repository": {
    "type": "git",
    "url": "git+https://github.com/huynle/hub.git",
    "directory": "packages/opencode-voice-shim"
  },
  "homepage": "https://github.com/huynle/hub#migrating-from-opencode-voice-or-opencode-hub",
  "bugs": {
    "url": "https://github.com/huynle/hub/issues"
  },
  "keywords": [
    "opencode",
    "opencode-plugin",
    "voice",
    "deprecated"
  ],
  "type": "module",
  "main": "./server.ts",
  "exports": {
    ".": "./server.ts",
    "./server": "./server.ts",
    "./tui": "./tui.ts",
    "./rpc": "./rpc.ts",
    "./package.json": "./package.json"
  },
  "files": [
    "server.ts",
    "tui.ts",
    "rpc.ts",
    "notice.ts",
    "README.md"
  ],
  "engines": {
    "bun": ">=1.3"
  },
  "publishConfig": {
    "access": "public"
  },
  "dependencies": {
    "@huynle/hub": "^0.6.0"
  }
}
